vector<vector<int> > multiply(const vector<vector<int> > &one, const vector<vector<int> > &two) {
    vector<vector<int> > res(m, vector<int>(m, 0));
    for (int i = 0; i < (int)m; i++) {
        for (int j = 0; j < (int)m; j++) {
            for (int k = 0; k < (int)m; k++) {
                res[i][j] += (int)((long long)one[i][k] * (long long)two[k][j] % mod_);
